const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体示意' },
      { kind: 'text', payload: '静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.5;
    var r = Math.max(14, Math.min(w, h) * 0.055);
    var ballY = h * 0.22;
    var ghostY = h * 0.86;
    var gap = r * 0.8;
    var vX = cx - gap;
    var gX = cx + gap;
    var vTipY = h * 0.8;
    var gTipY = h * 0.58;
    var headLen = Math.max(10, r * 0.65);
    var headHalf = headLen * 0.55;
    var startY = ballY + r * 0.6;
    var guideTop = ballY + r;
    var guideBottom = h * 0.94;
    function downArrowHead(x, tipY) {
      return [
        ['M', x - headHalf, tipY - headLen],
        ['L', x + headHalf, tipY - headLen],
        ['L', x, tipY],
        ['Z']
      ];
    }
    var guide = [['M', cx, guideTop], ['L', cx, guideBottom]];
    var ghost = visualSdk.circle(cx, ghostY, r);
    var ball = visualSdk.circle(cx, ballY, r);
    var vShaft = [['M', vX, startY], ['L', vX, vTipY - headLen * 0.8]];
    var gShaft = [['M', gX, startY], ['L', gX, gTipY - headLen * 0.8]];
    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'guide', commands: guide },
        { id: 'ghost', commands: ghost },
        { id: 'ball', commands: ball },
        { id: 'vShaft', commands: vShaft },
        { id: 'vHead', commands: downArrowHead(vX, vTipY) },
        { id: 'gShaft', commands: gShaft },
        { id: 'gHead', commands: downArrowHead(gX, gTipY) }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'guide', fill: '#8aa0b8', stroke: { width: 2, dash: [6, 6], cap: 'round' } },
          { type: 'path', pathId: 'ghost', fill: '#3a6ea522', stroke: { width: 2, dash: [6, 6] } },
          { type: 'path', pathId: 'ball', fill: '#3a6ea5', stroke: { width: 2 } },
          { type: 'path', pathId: 'vShaft', fill: '#c0392b', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'vHead', fill: '#c0392b' },
          { type: 'path', pathId: 'gShaft', fill: '#1f7a4d', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'gHead', fill: '#1f7a4d' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: cx, y: h * 0.06 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx, y: ballY - r - 8 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: vX - 10, y: (startY + vTipY) / 2 }, hAlign: 'right', vAlign: 'middle', color: '#c0392b' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: gX + 10, y: (startY + gTipY) / 2 }, hAlign: 'left', vAlign: 'middle', color: '#1f7a4d' }
        ]
      }
    };
  }
};
